import { http, HttpResponse, type HttpHandler } from "msw";

import { MOCK_OPERATIONS, type MockOperation } from "../generated/operations";
import { OPERATION_PROBLEMS } from "../generated/problems";
import { TENANTS } from "../fixtures";
import { tenantContext } from "./context";
import { authenticate, problem } from "./support";

/**
 * Base handlers for every operation this app can reach, answering the contract's own success example
 * (`mocks/generated/operations.ts`, regenerated by `pnpm gen:api`). They still behave like the API
 * where it matters to the UI: the bearer must be of the surface's audience, operator calls run in a
 * tenant context, and a suspended tenant's mutations are refused with `tenant.read_only` (D-082).
 * Hand-written handlers registered before these override them.
 */

function mswPath(path: string): string {
  return `*${path.replace(/\{(\w+)\}/g, ":$1")}`;
}

function surfaceOf(path: string): "auth" | "owner" | "staff" | "admin" {
  return path.split("/")[2] as "auth" | "owner" | "staff" | "admin";
}

function documents(operationId: string, code: string): boolean {
  return OPERATION_PROBLEMS[operationId]?.[code] !== undefined;
}

function respond(operation: MockOperation): Response {
  if (operation.example === undefined || operation.contentType === null) {
    return new HttpResponse(null, { status: operation.status });
  }
  const body = typeof operation.example === "string" ? operation.example : JSON.stringify(operation.example);
  return new HttpResponse(body, {
    status: operation.status,
    headers: { "content-type": operation.contentType, "x-request-id": crypto.randomUUID() },
  });
}

export function generatedHandlers(): HttpHandler[] {
  return MOCK_OPERATIONS.map((operation) =>
    http[operation.method](mswPath(operation.path), ({ request }) => {
      const surface = surfaceOf(operation.path);
      if (surface === "auth" || operation.path.endsWith("/realtime/stream")) return respond(operation);

      const auth = authenticate(request, surface === "admin" ? "platform" : "operator");
      if (!auth.ok) {
        return documents(operation.id, auth.code)
          ? problem(operation.id, auth.code)
          : problem(operation.id, "auth.unauthenticated");
      }
      if (auth.audience === "operator") {
        const context = tenantContext(request, auth.persona);
        if (!context.ok && documents(operation.id, context.code)) return problem(operation.id, context.code);
        if (context.ok && context.tenant === null && documents(operation.id, "tenant.context_required")) {
          return problem(operation.id, "tenant.context_required");
        }
        const readOnly = context.ok && context.tenant !== null && TENANTS[context.tenant].subscription.readOnly;
        if (readOnly && operation.method !== "get" && documents(operation.id, "tenant.read_only")) {
          return problem(operation.id, "tenant.read_only");
        }
      }
      return respond(operation);
    }),
  );
}
